    scanf("%d", &n);
    int left = n / 1000;
    int right = n % 1000;
    int left_sum = left / 100 + left / 10 % 10 + left % 10;
    int right_sum = right / 100 + right / 10 % 10 + right % 10;
    printf("%d\n", left_sum == right_sum);
    return 0;
}

