#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    int max = (a > b) * a + (a <= b) * b;
    int min = (a < b) * a + (a >= b) * b;
    printf("%d %d\n", max, min);
    return 0;
}

